/**
 * Token Manager — auto-renews the auth token when it expires.
 *
 * Refresh flow:
 *   1. Spawn scripts/extract-ai-token.mjs as a child process (headless Chrome)
 *   2. Wait for JSON result on stdout (60s timeout)
 *   3. On success: hot-reload process.env + persist to consumer's .env
 *   4. Notify registered listeners
 *
 * Concurrency guarantees:
 *   - All concurrent callers share a single refresh promise (no stampede)
 *   - Won't refresh again within MIN_REFRESH_INTERVAL_MS of the last success
 *
 * ── Portable path resolution ─────────────────────────────────────────────────
 * Two roots matter and they are NOT the same once this package is installed
 * into another project:
 *
 *   - CONSUMER_ROOT (= process.cwd()) — where the consumer's `.env` lives.
 *     The refreshed token is written here so the consumer's existing dotenv
 *     loader picks it up.
 *
 *   - PKG_ROOT (= resolved from import.meta.url) — where THIS package's files
 *     live. The extract-ai-token.mjs script ships with the package, so we
 *     must locate it relative to ourselves, not relative to the consumer's
 *     cwd (which is likely missing the script entirely).
 *
 * We probe candidate paths because the layout differs in source (running
 * with tsx) vs after build (running from dist/):
 *
 *   Source: src/providers/deepseek/tokenManager.ts  → ../../../scripts/...
 *   Built:  dist/providers/deepseek/tokenManager.js → ../../scripts/...
 *
 * Override either root with env vars:
 *   AI_PROVIDERS_DIRECT_SCRIPT  — absolute path to extract-ai-token.mjs
 *   AI_PROVIDERS_DIRECT_ENV     — absolute path to .env file to write
 */

import { spawn }                                  from "node:child_process";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, resolve }                 from "node:path";
import { fileURLToPath }                          from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));

/** Locate extract-ai-token.mjs by probing the layouts we know about. */
function findScriptPath(): string {
  const override = process.env.AI_PROVIDERS_DIRECT_SCRIPT;
  if (override) return resolve(override);

  const candidates = [
    // 1) Source layout: src/providers/deepseek/ → repo/scripts/
    join(HERE, "..", "..", "..", "scripts", "extract-ai-token.mjs"),
    // 2) Built layout (rootDir: src): dist/providers/deepseek/ → dist/scripts/
    join(HERE, "..", "..", "scripts", "extract-ai-token.mjs"),
    // 3) Fallback consumer cwd (legacy): allow the original "copy to your project" workflow
    join(process.cwd(), "scripts", "extract-ai-token.mjs"),
  ];
  for (const c of candidates) {
    if (existsSync(c)) return c;
  }
  // Return the first guess so the error message is informative.
  return candidates[0]!;
}

const SCRIPT_PATH = findScriptPath();
const ENV_PATH    = process.env.AI_PROVIDERS_DIRECT_ENV ?? join(process.cwd(), ".env");

const REFRESH_TIMEOUT_MS      = 60_000;  // abort browser launch after 60s
const MIN_REFRESH_INTERVAL_MS = 60_000;  // don't refresh more than once/min

// ── Types ─────────────────────────────────────────────────────────────────────

type RefreshSuccess = { success: true;  token: string; verifiedAs: string };
type RefreshFailure = { success: false; error: string; code?: string; token?: string };
type RefreshResult  = RefreshSuccess | RefreshFailure;

type Listener = (token: string) => void;

// ── Module state ──────────────────────────────────────────────────────────────

let _refreshPromise: Promise<RefreshResult> | null = null;
let _lastSuccessAt  = 0;
let _refreshCount   = 0;

const _listeners = new Set<Listener>();

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Register a callback invoked with the new token after every successful refresh.
 * Returns an unsubscribe function.
 */
export function onTokenRefresh(fn: Listener): () => void {
  _listeners.add(fn);
  return () => _listeners.delete(fn);
}

/** True while a refresh is actively running. */
export function isRefreshing(): boolean {
  return _refreshPromise !== null;
}

/** Milliseconds elapsed since the last successful refresh (Infinity = never). */
export function msSinceLastRefresh(): number {
  return _lastSuccessAt ? Date.now() - _lastSuccessAt : Infinity;
}

/** How many successful refreshes have occurred this server lifetime. */
export function refreshCount(): number {
  return _refreshCount;
}

/** Absolute path of the resolved extract-ai-token.mjs (useful for diagnostics). */
export function getScriptPath(): string {
  return SCRIPT_PATH;
}

/**
 * Trigger a token refresh. Concurrent callers share the same promise.
 *
 * Returns the new token on success.
 * Throws if the script fails (not logged in, Chrome missing, timeout, etc.).
 */
export async function refreshToken(): Promise<string> {
  // Debounce: recent success + token still set → skip
  if (
    Date.now() - _lastSuccessAt < MIN_REFRESH_INTERVAL_MS &&
    process.env.DEEPSEEK_USER_TOKEN
  ) {
    return process.env.DEEPSEEK_USER_TOKEN;
  }

  // Deduplicate concurrent callers
  if (_refreshPromise) {
    const result = await _refreshPromise;
    if (result.success) return result.token;
    throw new Error(`Token refresh failed: ${result.error}`);
  }

  if (!existsSync(SCRIPT_PATH)) {
    throw new Error(
      `extract-ai-token.mjs not found at ${SCRIPT_PATH}. ` +
      `Set AI_PROVIDERS_DIRECT_SCRIPT to its absolute path, or run from a layout where the script ships with the package.`,
    );
  }

  _refreshPromise = _runScript();

  try {
    const result = await _refreshPromise;

    if (result.success) {
      process.env.DEEPSEEK_USER_TOKEN = result.token;
      _persistToEnv(result.token);
      _lastSuccessAt = Date.now();
      _refreshCount++;
      for (const fn of _listeners) {
        try { fn(result.token); } catch { /* listener errors must not abort */ }
      }
      console.log(`[tokenManager] Token refreshed (verified as: ${result.verifiedAs})`);
      return result.token;
    }

    throw new Error(`Token refresh failed: ${result.error} (code: ${result.code ?? "unknown"})`);
  } finally {
    _refreshPromise = null;
  }
}

// ── Internal ──────────────────────────────────────────────────────────────────

function _runScript(): Promise<RefreshResult> {
  return new Promise(resolve => {
    // Pin the child to the consumer's cwd so .env / .deepseek-research/ land
    // in the consumer's project, NOT inside node_modules/ai-providers-direct/.
    const child = spawn("node", [SCRIPT_PATH], {
      stdio: ["ignore", "pipe", "pipe"],
      cwd:   process.cwd(),
      env:   { ...process.env },
    });

    let stdout = "";
    let stderr = "";

    child.stdout?.on("data", (d: Buffer) => { stdout += d.toString(); });
    child.stderr?.on("data", (d: Buffer) => { stderr += d.toString(); });

    const timer = setTimeout(() => {
      child.kill("SIGTERM");
      resolve({ success: false, error: "Refresh script timed out after 60s", code: "TIMEOUT" });
    }, REFRESH_TIMEOUT_MS);

    child.on("close", code => {
      clearTimeout(timer);
      const raw = stdout.trim();
      if (!raw) {
        resolve({
          success: false,
          error: `Script exited ${code} with no output. stderr: ${stderr.slice(0, 300)}`,
          code: "NO_OUTPUT",
        });
        return;
      }
      try {
        resolve(JSON.parse(raw) as RefreshResult);
      } catch {
        resolve({
          success: false,
          error: `Script output is not valid JSON: ${raw.slice(0, 200)}`,
          code: "PARSE_ERROR",
        });
      }
    });

    child.on("error", err => {
      clearTimeout(timer);
      resolve({
        success: false,
        error: `Failed to spawn refresh script: ${(err as Error).message}`,
        code: "SPAWN_ERROR",
      });
    });
  });
}

/**
 * Write/replace DEEPSEEK_USER_TOKEN in the consumer's .env file.
 * Reads the whole file, replaces the matching line (or appends), writes back.
 * Non-fatal: in-memory update already applied before this is called.
 */
function _persistToEnv(token: string): void {
  try {
    if (!existsSync(ENV_PATH)) {
      writeFileSync(ENV_PATH, `DEEPSEEK_USER_TOKEN=${token}\n`, "utf8");
      return;
    }
    // Normalise to LF so CRLF files on Windows don't leave \r in the token line.
    const content = readFileSync(ENV_PATH, "utf8").replace(/\r\n/g, "\n");
    const lines   = content.split("\n");
    let found     = false;

    const updated = lines.map(line => {
      if (line.match(/^DEEPSEEK_USER_TOKEN\s*=/)) {
        found = true;
        return `DEEPSEEK_USER_TOKEN=${token}`;
      }
      return line;
    });

    if (!found) updated.push(`DEEPSEEK_USER_TOKEN=${token}`);

    writeFileSync(ENV_PATH, updated.join("\n"), "utf8");
    console.log(`[tokenManager] ${ENV_PATH} updated with new token`);
  } catch (err) {
    console.error("[tokenManager] Failed to persist token:", (err as Error).message);
  }
}
